INSERT INTO feature VALUES('native-conversion','conversion','Endpoint pairs decided on the emitter','certified-conversion','implemented','notable',NULL,'A `Path.here` pair is run on the emitter and read back, each variable its endpoints read an accumulator whose force or application grows its spine, and two equal readings decide it without the conversion machine; the kernel converts that pair by its own evaluation within the replay''s budget in place of replaying a dialogue, a decline refused. A pair whose run steps a native operation, which the kernel holds as an opaque constant, spends the tier''s fuel, observes a free variable other than by a force or an application, or reads apart goes to the machine as before. Under `check --admit native-conversion` the kernel takes a closed pair''s answer as an admitted result without deriving it, and the emitter is in the trusted base for the run: the report counts the results taken, the verdict names the policy and the tier, and a declaration that took one keeps no recorded verdict.','core-checker core-incremental surface-dispatcher surface-driver kernel-core kernel-term kernel-conversion-trace core-sequent runtime-emitter runtime-stencils','corpus/model/conversion/fibonacci.gandr corpus/model/conversion/factorial.gandr corpus/model/conversion/recursion-without-allocation.gandr corpus/model/conversion/pigeonhole.gandr corpus/model/conversion/lucas-lehmer.gandr corpus/model/conversion/church-iteration.gandr corpus/pathological/data/conversion-budget.gandr corpus/pathological/effects/grade-algebra.gandr','corpus/model/conversion/fibonacci.gandr','#3558');
